#define FAFFT_GFT_MUL_CONST_TABLES_H

/*
 * Constant-multiply tables for the FFT v-part (layer constants V17..V27).
 *
 * Multiplying a bitsliced gf32v_array by a fixed field constant is a linear map
 * over GF(2): output plane j is a fixed XOR of input planes. MAT_Vxx[j] is the
 * bitmask of input planes that XOR into output plane j.
 *
 * GENERATED, then verified to reproduce fafft_gft_mul_vXX_gf32v() exactly on
 * 2000 random inputs each (host check). See gft_mul_vi_gf32v.c for the circuits.
 * Do not edit by hand; regenerate from those circuits if they ever change.
 */

