/* v-constant -> table, or 0 if not a known FFT layer constant. */
static inline const uint32_t *fafft_gft_const_table(uint32_t v) {
    switch (v) {
        case 0x002e597u: return MAT_V17;
        case 0x0052257u: return MAT_V18;
        case 0x009b170u: return MAT_V19;
        case 0x013572fu: return MAT_V20;
        case 0x02c7d24u: return MAT_V21;
        case 0x0573762u: return MAT_V22;
        case 0x092f9fau: return MAT_V23;
        case 0x12f1b8du: return MAT_V24;
        case 0x2e55791u: return MAT_V25;
        case 0x52267c0u: return MAT_V26;
        case 0x9b120beu: return MAT_V27;
        default:         return 0;
    }
}

